import pandas as pd
import numpy as np
import json
import os

# ─────────────────────────────────────────────
# 1. LOAD & PREPARE DATA
# ─────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['year'] = df['year'].astype(int)
df['job_survival_class'] = df['job_survival_class'].astype(int)
df['skill_demand_score'] = df['skill_demand_score'].astype(int)

total_rows = len(df)
year_min, year_max = int(df['year'].min()), int(df['year'].max())
job_titles = sorted(df['job_title'].unique())
countries = sorted(df['country'].unique())
exp_levels = sorted(df['experience_level'].unique())
skills = sorted(df['primary_skill'].unique())
edu_levels = sorted(df['education_level'].unique())

# ─────────────────────────────────────────────
# 2. COMPUTE ALL KPIs AND ANALYSIS DATA
# ─────────────────────────────────────────────

# --- KPI 1: Average AI Risk Score ---
risk_by_year = df.groupby('year')['ai_risk_score'].mean().reset_index()
risk_by_year.columns = ['year', 'avg_risk']

risk_by_job = df.groupby('job_title')['ai_risk_score'].mean().sort_values(ascending=False).reset_index()
risk_by_job.columns = ['job_title', 'avg_risk']

risk_by_country = df.groupby('country')['ai_risk_score'].mean().sort_values(ascending=False).reset_index()
risk_by_country.columns = ['country', 'avg_risk']

risk_by_exp = df.groupby('experience_level')['ai_risk_score'].mean().sort_values(ascending=False).reset_index()
risk_by_exp.columns = ['experience_level', 'avg_risk']

risk_by_job_year = df.groupby(['year', 'job_title'])['ai_risk_score'].mean().reset_index()

risk_by_category = df.groupby('ai_risk_category').size().reset_index(name='count')
risk_cat_order = ['Low Risk', 'Medium Risk', 'High Risk']
risk_by_category['ai_risk_category'] = pd.Categorical(risk_by_category['ai_risk_category'], categories=risk_cat_order, ordered=True)
risk_by_category = risk_by_category.sort_values('ai_risk_category')

# YoY risk change
risk_yoy = risk_by_year.copy()
risk_yoy['risk_change'] = risk_yoy['avg_risk'].diff()
risk_yoy['risk_change_pct'] = risk_yoy['avg_risk'].pct_change() * 100

# Risk by job and country (pivot for heatmap-like analysis)
risk_job_country = df.groupby(['job_title', 'country'])['ai_risk_score'].mean().unstack(fill_value=0).round(3)

# --- KPI 2: Median Salary ---
salary_by_year = df.groupby('year')['salary'].median().reset_index()
salary_by_year.columns = ['year', 'median_salary']

salary_by_country = df.groupby('country')['salary'].median().sort_values(ascending=False).reset_index()
salary_by_country.columns = ['country', 'median_salary']

salary_by_exp = df.groupby('experience_level')['salary'].median().sort_values(ascending=False).reset_index()
salary_by_exp.columns = ['experience_level', 'median_salary']

salary_by_edu = df.groupby('education_level')['salary'].median().sort_values(ascending=False).reset_index()
salary_by_edu.columns = ['education_level', 'median_salary']

salary_by_job = df.groupby('job_title')['salary'].median().sort_values(ascending=False).reset_index()
salary_by_job.columns = ['job_title', 'median_salary']

salary_by_job_year = df.groupby(['year', 'job_title'])['salary'].median().reset_index()

salary_by_bucket = df.groupby('salary_bucket').size().reset_index(name='count')
bucket_order = ['Low', 'Medium', 'High']
salary_by_bucket['salary_bucket'] = pd.Categorical(salary_by_bucket['salary_bucket'], categories=bucket_order, ordered=True)
salary_by_bucket = salary_by_bucket.sort_values('salary_bucket')

# Salary x AI Risk correlation
salary_risk_corr = df[['salary', 'ai_risk_score']].corr().iloc[0, 1]

# Salary by risk category
salary_by_risk_cat = df.groupby('ai_risk_category')['salary'].median().reindex(risk_cat_order).reset_index()
salary_by_risk_cat.columns = ['ai_risk_category', 'median_salary']

# Salary and risk over time (correlation trend)
salary_risk_by_year = df.groupby('year').agg(
    median_salary=('salary', 'median'),
    avg_risk=('ai_risk_score', 'mean')
).reset_index()

# Salary growth rate by job title
salary_first = df[df['year'].isin([2015, 2016, 2017])].groupby('job_title')['salary'].mean()
salary_last = df[df['year'].isin([2033, 2034, 2035])].groupby('job_title')['salary'].mean()
salary_growth = ((salary_last - salary_first) / salary_first * 100).sort_values(ascending=False).reset_index()
salary_growth.columns = ['job_title', 'pct_growth']

# --- KPI 3: Job Survival Rate ---
survival_by_year = df.groupby('year')['job_survival_class'].apply(
    lambda x: (x >= 1).sum() / len(x) * 100
).reset_index()
survival_by_year.columns = ['year', 'survival_rate']

survival_by_job = df.groupby('job_title')['job_survival_class'].apply(
    lambda x: (x >= 1).sum() / len(x) * 100
).sort_values(ascending=False).reset_index()
survival_by_job.columns = ['job_title', 'survival_rate']

survival_by_country = df.groupby('country')['job_survival_class'].apply(
    lambda x: (x >= 1).sum() / len(x) * 100
).sort_values(ascending=False).reset_index()
survival_by_country.columns = ['country', 'survival_rate']

# Survival class distribution
survival_dist = df.groupby('job_survival_class').size().reset_index(name='count')
survival_dist['label'] = survival_dist['job_survival_class'].map({
    0: 'At Risk', 1: 'Moderate Survival', 2: 'Strong Survival'
})

# Best combinations for survival
survival_combo = df.groupby(['job_title', 'primary_skill', 'education_level', 'country'])['job_survival_class'].apply(
    lambda x: (x >= 1).sum() / len(x) * 100
).reset_index()
survival_combo.columns = ['job_title', 'primary_skill', 'education_level', 'country', 'survival_rate']
survival_combo_top = survival_combo.sort_values('survival_rate', ascending=False).head(15)

# Worst combinations
survival_combo_bottom = survival_combo.sort_values('survival_rate', ascending=True).head(10)

# --- KPI 4: Average Skill Demand Score ---
skill_demand_by_year = df.groupby(['year', 'primary_skill'])['skill_demand_score'].mean().reset_index()

skill_demand_overall = df.groupby('primary_skill')['skill_demand_score'].mean().sort_values(ascending=False).reset_index()
skill_demand_overall.columns = ['primary_skill', 'avg_demand']

# Skill demand growth
skill_first = df[df['year'].isin([2015, 2016, 2017])].groupby('primary_skill')['skill_demand_score'].mean()
skill_last = df[df['year'].isin([2033, 2034, 2035])].groupby('primary_skill')['skill_demand_score'].mean()
skill_growth = ((skill_last - skill_first) / skill_first * 100).sort_values(ascending=False).reset_index()
skill_growth.columns = ['primary_skill', 'pct_growth']

# Skill demand vs AI risk
skill_risk = df.groupby('primary_skill').agg(
    avg_demand=('skill_demand_score', 'mean'),
    avg_risk=('ai_risk_score', 'mean')
).reset_index()

# Skill demand vs job survival
skill_survival = df.groupby('primary_skill').agg(
    avg_demand=('skill_demand_score', 'mean'),
    survival_rate=('job_survival_class', lambda x: (x >= 1).sum() / len(x) * 100)
).reset_index()

# --- KPI 5: Total Job Openings Trend ---
openings_by_year = df.groupby('year')['job_openings'].sum().reset_index()

openings_by_job_year = df.groupby(['year', 'job_title'])['job_openings'].sum().reset_index()

openings_by_job = df.groupby('job_title')['job_openings'].sum().sort_values(ascending=False).reset_index()

# Openings growth
openings_first = df[df['year'].isin([2015, 2016, 2017])].groupby('job_title')['job_openings'].sum()
openings_last = df[df['year'].isin([2033, 2034, 2035])].groupby('job_title')['job_openings'].sum()
openings_growth = ((openings_last - openings_first) / openings_first * 100).sort_values(ascending=False).reset_index()
openings_growth.columns = ['job_title', 'pct_growth']

# ─────────────────────────────────────────────
# 3. EXECUTIVE OVERVIEW KEY FINDINGS
# ─────────────────────────────────────────────
overall_risk = df['ai_risk_score'].mean()
overall_survival = (df['job_survival_class'] >= 1).sum() / len(df) * 100
overall_median_salary = df['salary'].median()

earliest_risk = risk_by_year[risk_by_year['year'] == year_min]['avg_risk'].values[0]
latest_risk = risk_by_year[risk_by_year['year'] == year_max]['avg_risk'].values[0]
risk_change_total = ((latest_risk - earliest_risk) / earliest_risk) * 100

earliest_salary = salary_by_year[salary_by_year['year'] == year_min]['median_salary'].values[0]
latest_salary = salary_by_year[salary_by_year['year'] == year_max]['median_salary'].values[0]
salary_change_total = ((latest_salary - earliest_salary) / earliest_salary) * 100

highest_risk_job = risk_by_job.iloc[0]['job_title']
highest_risk_val = risk_by_job.iloc[0]['avg_risk']
lowest_risk_job = risk_by_job.iloc[-1]['job_title']
lowest_risk_val = risk_by_job.iloc[-1]['avg_risk']

highest_demand_skill = skill_demand_overall.iloc[0]['primary_skill']
highest_demand_val = skill_demand_overall.iloc[0]['avg_demand']

# ─────────────────────────────────────────────
# 4. GENERATE CHART DATA AS JSON
# ─────────────────────────────────────────────

def df_to_chart_data(df, x_col, y_col, label=None):
    """Convert dataframe to chart.js dataset format"""
    return {
        'labels': df[x_col].tolist(),
        'data': [round(v, 3) for v in df[y_col].tolist()],
        'label': label or y_col
    }

# Color palettes
CHART_COLORS = [
    'rgba(54, 162, 235, 0.7)',   # blue
    'rgba(255, 99, 132, 0.7)',   # red
    'rgba(75, 192, 192, 0.7)',   # teal
    'rgba(255, 206, 86, 0.7)',   # yellow
    'rgba(153, 102, 255, 0.7)',  # purple
    'rgba(255, 159, 64, 0.7)',   # orange
    'rgba(199, 199, 199, 0.7)',  # gray
    'rgba(83, 102, 255, 0.7)',   # indigo
    'rgba(255, 99, 255, 0.7)',   # pink
    'rgba(99, 255, 132, 0.7)',   # green
]

CHART_BORDERS = [
    'rgba(54, 162, 235, 1)',
    'rgba(255, 99, 132, 1)',
    'rgba(75, 192, 192, 1)',
    'rgba(255, 206, 86, 1)',
    'rgba(153, 102, 255, 1)',
    'rgba(255, 159, 64, 1)',
    'rgba(199, 199, 199, 1)',
    'rgba(83, 102, 255, 1)',
    'rgba(255, 99, 255, 1)',
    'rgba(99, 255, 132, 1)',
]

RISK_COLORS = {
    'Low Risk': 'rgba(75, 192, 192, 0.7)',
    'Medium Risk': 'rgba(255, 206, 86, 0.7)',
    'High Risk': 'rgba(255, 99, 132, 0.7)',
}

SURVIVAL_COLORS = {
    'At Risk': 'rgba(255, 99, 132, 0.7)',
    'Moderate Survival': 'rgba(255, 206, 86, 0.7)',
    'Strong Survival': 'rgba(75, 192, 192, 0.7)',
}

# Build chart configurations
charts = {}

# Chart 1: Average AI Risk Score Over Time
charts['risk_over_time'] = {
    'type': 'line',
    'data': {
        'labels': risk_by_year['year'].tolist(),
        'datasets': [{
            'label': 'Average AI Risk Score',
            'data': [round(v, 3) for v in risk_by_year['avg_risk'].tolist()],
            'borderColor': 'rgba(255, 99, 132, 1)',
            'backgroundColor': 'rgba(255, 99, 132, 0.1)',
            'fill': True,
            'tension': 0.3,
            'pointRadius': 4,
        }]
    },
    'options': {
        'responsive': True,
        'scales': {
            'y': {'beginAtZero': False, 'title': {'display': True, 'text': 'Avg AI Risk Score'}},
            'x': {'title': {'display': True, 'text': 'Year'}}
        },
        'plugins': {'legend': {'display': True}}
    }
}

# Chart 2: AI Risk by Job Title (bar)
charts['risk_by_job'] = {
    'type': 'bar',
    'data': {
        'labels': risk_by_job['job_title'].tolist(),
        'datasets': [{
            'label': 'Average AI Risk Score',
            'data': [round(v, 3) for v in risk_by_job['avg_risk'].tolist()],
            'backgroundColor': [CHART_COLORS[i % len(CHART_COLORS)] for i in range(len(risk_by_job))],
            'borderColor': [CHART_BORDERS[i % len(CHART_BORDERS)] for i in range(len(risk_by_job))],
            'borderWidth': 1,
        }]
    },
    'options': {
        'responsive': True,
        'indexAxis': 'y',
        'scales': {
            'x': {'beginAtZero': True, 'title': {'display': True, 'text': 'Avg AI Risk Score'}},
        },
        'plugins': {'legend': {'display': False}}
    }
}

# Chart 3: Risk by Country
charts['risk_by_country'] = {
    'type': 'bar',
    'data': {
        'labels': risk_by_country['country'].tolist(),
        'datasets': [{
            'label': 'Average AI Risk Score',
            'data': [round(v, 3) for v in risk_by_country['avg_risk'].tolist()],
            'backgroundColor': [CHART_COLORS[i % len(CHART_COLORS)] for i in range(len(risk_by_country))],
            'borderColor': [CHART_BORDERS[i % len(CHART_BORDERS)] for i in range(len(risk_by_country))],
            'borderWidth': 1,
        }]
    },
    'options': {
        'responsive': True,
        'scales': {
            'y': {'beginAtZero': True, 'title': {'display': True, 'text': 'Avg AI Risk Score'}},
        },
        'plugins': {'legend': {'display': False}}
    }
}

# Chart 4: Risk by Experience Level
charts['risk_by_exp'] = {
    'type': 'bar',
    'data': {
        'labels': risk_by_exp['experience_level'].tolist(),
        'datasets': [{
            'label': 'Average AI Risk Score',
            'data': [round(v, 3) for v in risk_by_exp['avg_risk'].tolist()],
            'backgroundColor': CHART_COLORS[:len(risk_by_exp)],
            'borderColor': CHART_BORDERS[:len(risk_by_exp)],
            'borderWidth': 1,
        }]
    },
    'options': {
        'responsive': True,
        'scales': {
            'y': {'beginAtZero': True, 'title': {'display': True, 'text': 'Avg AI Risk Score'}},
        },
        'plugins': {'legend': {'display': False}}
    }
}

# Chart 5: Risk Category Distribution (doughnut)
charts['risk_category_dist'] = {
    'type': 'doughnut',
    'data': {
        'labels': risk_by_category['ai_risk_category'].tolist(),
        'datasets': [{
            'data': risk_by_category['count'].tolist(),
            'backgroundColor': [RISK_COLORS.get(c, 'rgba(199,199,199,0.7)') for c in risk_by_category['ai_risk_category'].tolist()],
            'borderWidth': 2,
        }]
    },
    'options': {
        'responsive': True,
        'plugins': {'legend': {'position': 'bottom'}}
    }
}

# Chart 6: Risk over time by job title (multi-line)
job_year_pivot = risk_by_job_year.pivot(index='year', columns='job_title', values='ai_risk_score').fillna(0)
charts['risk_by_job_year'] = {
    'type': 'line',
    'data': {
        'labels': job_year_pivot.index.tolist(),
        'datasets': [{
            'label': col,
            'data': [round(v, 3) for v in job_year_pivot[col].tolist()],
            'borderColor': CHART_BORDERS[i % len(CHART_BORDERS)],
            'backgroundColor': 'transparent',
            'tension': 0.3,
            'pointRadius': 2,
        } for i, col in enumerate(job_year_pivot.columns)]
    },
    'options': {
        'responsive': True,
        'scales': {
            'y': {'title': {'display': True, 'text': 'Avg AI Risk Score'}},
            'x': {'title': {'display': True, 'text': 'Year'}}
        },
        'plugins': {'legend': {'position': 'bottom'}}
    }
}

# Chart 7: Median Salary Over Time
charts['salary_over_time'] = {
    'type': 'line',
    'data': {
        'labels': salary_by_year['year'].tolist(),
        'datasets': [{
            'label': 'Median Salary (USD)',
            'data': [round(v, 2) for v in salary_by_year['median_salary'].tolist()],
            'borderColor': 'rgba(75, 192, 192, 1)',
            'backgroundColor': 'rgba(75, 192, 192, 0.1)',
            'fill': True,
            'tension': 0.3,
            'pointRadius': 4,
        }]
    },
    'options': {
        'responsive': True,
        'scales': {
            'y': {'title': {'display': True, 'text': 'Median Salary (USD)'}},
            'x': {'title': {'display': True, 'text': 'Year'}}
        },
    }
}

# Chart 8: Salary by Country
charts['salary_by_country'] = {
    'type': 'bar',
    'data': {
        'labels': salary_by_country['country'].tolist(),
        'datasets': [{
            'label': 'Median Salary (USD)',
            'data': [round(v, 2) for v in salary_by_country['median_salary'].tolist()],
            'backgroundColor': [CHART_COLORS[i % len(CHART_COLORS)] for i in range(len(salary_by_country))],
            'borderColor': [CHART_BORDERS[i % len(CHART_BORDERS)] for i in range(len(salary_by_country))],
