worst_survival_rate = survival_by_job.iloc[-1]['survival_rate']

# Salary risk insight
high_risk_avg_salary = df[df['ai_risk_category'] == 'High Risk']['salary'].median()
low_risk_avg_salary = df[df['ai_risk_category'] == 'Low Risk']['salary'].median()
salary_risk_gap = ((low_risk_avg_salary - high_risk_avg_salary) / high_risk_avg_salary) * 100

# Education vs survival
edu_survival = df.groupby('education_level')['job_survival_class'].apply(
    lambda x: (x >= 1).sum() / len(x) * 100
).sort_values(ascending=False)
best_edu = edu_survival.index[0]
best_edu_rate = edu_survival.values[0]

# Experience vs survival
exp_survival = df.groupby('experience_level')['job_survival_class'].apply(
    lambda x: (x >= 1).sum() / len(x) * 100
).sort_values(ascending=False)
