    ['Job Title', 'Avg AI Risk Score', 'Risk Category'],
    [(r['job_title'], f"{r['avg_risk']:.3f}", 'High' if r['avg_risk'] >= 0.5 else 'Medium' if r['avg_risk'] >= 0.3 else 'Low')
     for _, r in risk_by_job.iterrows()],
    'risk-job-table'
)

