import pandas as pd
import numpy as np
import json
import os

# ─────────────────────────────────────────────
# 1. LOAD & PREPARE DATA
# ─────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['year'] = df['year'].astype(int)
df['job_survival_class'] = df['job_survival_class'].astype(int)
