# --- KPI 1: Average AI Risk Score ---
risk_by_year = df.groupby('year')['ai_risk_score'].mean().reset_index()
risk_by_year.columns = ['year', 'avg_risk']

risk_by_job = df.groupby('job_title')['ai_risk_score'].mean().sort_values(ascending=False).reset_index()
risk_by_job.columns = ['job_title', 'avg_risk']

risk_by_country = df.groupby('country')['ai_risk_score'].mean().sort_values(ascending=False).reset_index()
risk_by_country.columns = ['country', 'avg_risk']

risk_by_exp = df.groupby('experience_level')['ai_risk_score'].mean().sort_values(ascending=False).reset_index()
risk_by_exp.columns = ['experience_level', 'avg_risk']

risk_by_job_year = df.groupby(['year', 'job_title'])['ai_risk_score'].mean().reset_index()

risk_by_category = df.groupby('ai_risk_category').size().reset_index(name='count')
risk_cat_order = ['Low Risk', 'Medium Risk', 'High Risk']
risk_by_category['ai_risk_category'] = pd.Categorical(risk_by_category['ai_risk_category'], categories=risk_cat_order, ordered=True)
risk_by_category = risk_by_category.sort_values('ai_risk_category')

# YoY risk change
risk_yoy = risk_by_year.copy()
risk_yoy['risk_change'] = risk_yoy['avg_risk'].diff()
risk_yoy['risk_change_pct'] = risk_yoy['avg_risk'].pct_change() * 100

# Risk by job and country (pivot for heatmap-like analysis)
risk_job_country = df.groupby(['job_title', 'country'])['ai_risk_score'].mean().unstack(fill_value=0).round(3)

# --- KPI 2: Median Salary ---
salary_by_year = df.groupby('year')['salary'].median().reset_index()
salary_by_year.columns = ['year', 'median_salary']

salary_by_country = df.groupby('country')['salary'].median().sort_values(ascending=False).reset_index()
salary_by_country.columns = ['country', 'median_salary']

salary_by_exp = df.groupby('experience_level')['salary'].median().sort_values(ascending=False).reset_index()
salary_by_exp.columns = ['experience_level', 'median_salary']

salary_by_edu = df.groupby('education_level')['salary'].median().sort_values(ascending=False).reset_index()
salary_by_edu.columns = ['education_level', 'median_salary']

salary_by_job = df.groupby('job_title')['salary'].median().sort_values(ascending=False).reset_index()
salary_by_job.columns = ['job_title', 'median_salary']

salary_by_job_year = df.groupby(['year', 'job_title'])['salary'].median().reset_index()

salary_by_bucket = df.groupby('salary_bucket').size().reset_index(name='count')
bucket_order = ['Low', 'Medium', 'High']
salary_by_bucket['salary_bucket'] = pd.Categorical(salary_by_bucket['salary_bucket'], categories=bucket_order, ordered=True)
salary_by_bucket = salary_by_bucket.sort_values('salary_bucket')

# Salary x AI Risk correlation
salary_risk_corr = df[['salary', 'ai_risk_score']].corr().iloc[0, 1]

# Salary by risk category
salary_by_risk_cat = df.groupby('ai_risk_category')['salary'].median().reindex(risk_cat_order).reset_index()
salary_by_risk_cat.columns = ['ai_risk_category', 'median_salary']

# Salary and risk over time (correlation trend)
salary_risk_by_year = df.groupby('year').agg(
    median_salary=('salary', 'median'),
    avg_risk=('ai_risk_score', 'mean')
).reset_index()

# Salary growth rate by job title
salary_first = df[df['year'].isin([2015, 2016, 2017])].groupby('job_title')['salary'].mean()
salary_last = df[df['year'].isin([2033, 2034, 2035])].groupby('job_title')['salary'].mean()
salary_growth = ((salary_last - salary_first) / salary_first * 100).sort_values(ascending=False).reset_index()
salary_growth.columns = ['job_title', 'pct_growth']

# --- KPI 3: Job Survival Rate ---
