# --- KPI 4: Average Skill Demand Score ---
skill_demand_by_year = df.groupby(['year', 'primary_skill'])['skill_demand_score'].mean().reset_index()

skill_demand_overall = df.groupby('primary_skill')['skill_demand_score'].mean().sort_values(ascending=False).reset_index()
skill_demand_overall.columns = ['primary_skill', 'avg_demand']

# Skill demand growth
skill_first = df[df['year'].isin([2015, 2016, 2017])].groupby('primary_skill')['skill_demand_score'].mean()
skill_last = df[df['year'].isin([2033, 2034, 2035])].groupby('primary_skill')['skill_demand_score'].mean()
skill_growth = ((skill_last - skill_first) / skill_first * 100).sort_values(ascending=False).reset_index()
skill_growth.columns = ['primary_skill', 'pct_growth']

# Skill demand vs AI risk
skill_risk = df.groupby('primary_skill').agg(
    avg_demand=('skill_demand_score', 'mean'),
    avg_risk=('ai_risk_score', 'mean')
).reset_index()

# Skill demand vs job survival
skill_survival = df.groupby('primary_skill').agg(
    avg_demand=('skill_demand_score', 'mean'),
    survival_rate=('job_survival_class', lambda x: (x >= 1).sum() / len(x) * 100)
).reset_index()

# --- KPI 5: Total Job Openings Trend ---
openings_by_year = df.groupby('year')['job_openings'].sum().reset_index()

openings_by_job_year = df.groupby(['year', 'job_title'])['job_openings'].sum().reset_index()

openings_by_job = df.groupby('job_title')['job_openings'].sum().sort_values(ascending=False).reset_index()

# Openings growth
openings_first = df[df['year'].isin([2015, 2016, 2017])].groupby('job_title')['job_openings'].sum()
openings_last = df[df['year'].isin([2033, 2034, 2035])].groupby('job_title')['job_openings'].sum()
openings_growth = ((openings_last - openings_first) / openings_first * 100).sort_values(ascending=False).reset_index()
openings_growth.columns = ['job_title', 'pct_growth']

# ─────────────────────────────────────────────
# 3. EXECUTIVE OVERVIEW KEY FINDINGS
# ─────────────────────────────────────────────
overall_risk = df['ai_risk_score'].mean()
overall_survival = (df['job_survival_class'] >= 1).sum() / len(df) * 100
overall_median_salary = df['salary'].median()

earliest_risk = risk_by_year[risk_by_year['year'] == year_min]['avg_risk'].values[0]
latest_risk = risk_by_year[risk_by_year['year'] == year_max]['avg_risk'].values[0]
