highest_risk_job = risk_by_job.iloc[0]['job_title']
highest_risk_val = risk_by_job.iloc[0]['avg_risk']
lowest_risk_job = risk_by_job.iloc[-1]['job_title']
lowest_risk_val = risk_by_job.iloc[-1]['avg_risk']

highest_demand_skill = skill_demand_overall.iloc[0]['primary_skill']
