def build_table(headers, rows, id_attr=""):
    html = f'<table id="{id_attr}"><thead><tr>'
    for h in headers:
        html += f'<th>{h}</th>'
    html += '</tr></thead><tbody>'
    for row in rows:
        html += '<tr>'
        for cell in row:
            html += f'<td>{cell}</td>'
        html += '</tr>'
    html += '</tbody></table>'
    return html

# Risk by job table
risk_job_table = build_table(
    ['Job Title', 'Avg AI Risk Score', 'Risk Category'],
    [(r['job_title'], f"{r['avg_risk']:.3f}", 'High' if r['avg_risk'] >= 0.5 else 'Medium' if r['avg_risk'] >= 0.3 else 'Low')
     for _, r in risk_by_job.iterrows()],
    'risk-job-table'
)

# Risk by country table
risk_country_table = build_table(
    ['Country', 'Avg AI Risk Score'],
    [(r['country'], f"{r['avg_risk']:.3f}") for _, r in risk_by_country.iterrows()],
    'risk-country-table'
)

# Salary by job table
