def df_to_chart_data(df, x_col, y_col, label=None):
    """Convert dataframe to chart.js dataset format"""
    return {
        'labels': df[x_col].tolist(),
        'data': [round(v, 3) for v in df[y_col].tolist()],
        'label': label or y_col
