from html.parser import HTMLParser
import sys

class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.tag_stack = []
        self.void_elements = {'br', 'hr', 'img', 'input', 'meta', 'link', 'area', 'base', 'col', 'embed', 'param', 'source', 'track', 'wbr'}

    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.tag_stack.append(tag)

    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.tag_stack and self.tag_stack[-1] == tag:
            self.tag_stack.pop()
        else:
            self.errors.append(f'Mismatched tag: </{tag}>')

with open('/app/output/final_report.html', 'r') as f:
    content = f.read()

validator = HTMLValidator()
try:
    validator.feed(content)
    print(f'HTML parsing completed')
    if validator.errors:
        for e in validator.errors[:10]:
            print(f'  Error: {e}')
    else:
        print('  No structural errors detected')
    print(f'  Remaining open tags: {len(validator.tag_stack)}')
except Exception as e:
    print(f'Parse error: {e}')

# Check key sections exist
sections = ['executive-overview', 'automation-risk', 'salary-trends', 'skills-demand', 'job-survival', 'recommendations']
for s in sections:
    if f'id=\"{s}\"' in content:
        print(f'  Section [{s}]: FOUND')
    else:
        print(f'  Section [{s}]: MISSING')

# Check Chart.js CDN
if 'chart.js' in content or 'chart.umd' in content:
    print('  Chart.js CDN: INCLUDED')
else:
    print('  Chart.js CDN: MISSING')
"

